/**
 * Validate Email Payload & Security Sanitization
 * Enforces strict schema, rejects unauthorized SMTP injection,
 * and renders professional HTML email templates with inline CSS.
 *
 * Brand colors:
 *   Primary blue : #2563EB
 *   Dark navy    : #172554
 *   Background   : #F3F6FB
 *   Success green: #16A34A
 *   Warning amber: #D97706
 *   Error red    : #DC2626
 *   Text dark    : #1E293B
 *   Text muted   : #64748B
 */

const payload = $json.body || $json;

// 1. Allowed keys strictly matching supported schema
const ALLOWED_KEYS = new Set([
  'to', 'subject', 'message', 'email_type', 'template',
  'recipient_name', 'sender_name', 'reply_to', 'template_data'
]);

for (const key of Object.keys(payload)) {
  if (!ALLOWED_KEYS.has(key)) {
    return [{ json: { isValid: false, statusCode: 400,
      errorMessage: `Disallowed payload attribute: '${key}'` } }];
  }
}

// 2. Validate recipient email
const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
if (!payload.to || typeof payload.to !== 'string' || !emailRegex.test(payload.to.trim())) {
  return [{ json: { isValid: false, statusCode: 400,
    errorMessage: "Field 'to' must be a single valid email address." } }];
}

// 3. Validate reply_to if provided
if (payload.reply_to && (typeof payload.reply_to !== 'string' || !emailRegex.test(payload.reply_to.trim()))) {
  return [{ json: { isValid: false, statusCode: 400,
    errorMessage: "Field 'reply_to' must be a valid email address." } }];
}

// 4. Validate email_type
const emailType = (payload.email_type || 'html').toLowerCase();
if (!['html', 'text'].includes(emailType)) {
  return [{ json: { isValid: false, statusCode: 400,
    errorMessage: "Field 'email_type' must be 'html' or 'text'." } }];
}

// 5. HTML wrapper helper — table-based layout, inline CSS, responsive-safe
const e = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const BADGE_COLORS = {
  open:        { bg:'#DBEAFE', text:'#1D4ED8' },
  assigned:    { bg:'#E0E7FF', text:'#4338CA' },
  in_progress: { bg:'#FEF9C3', text:'#854D0E' },
  pending:     { bg:'#FEF3C7', text:'#92400E' },
  resolved:    { bg:'#DCFCE7', text:'#15803D' },
  closed:      { bg:'#F1F5F9', text:'#475569' },
  low:         { bg:'#F0FDF4', text:'#15803D' },
  medium:      { bg:'#FEF9C3', text:'#854D0E' },
  high:        { bg:'#FEF3C7', text:'#92400E' },
  critical:    { bg:'#FEE2E2', text:'#991B1B' }
};

const badge = (label) => {
  const key = String(label || '').toLowerCase().replace(/ /g,'_');
  const c = BADGE_COLORS[key] || { bg:'#E2E8F0', text:'#475569' };
  return `<span style="display:inline-block;padding:2px 10px;border-radius:12px;font-size:12px;font-weight:600;background:${c.bg};color:${c.text}">${e(label)}</span>`;
};

const htmlWrap = (accentColor, iconEmoji, titleText, bodyHtml) => `<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${e(titleText)}</title></head>
<body style="margin:0;padding:0;background:#F3F6FB;font-family:'Segoe UI',Arial,sans-serif">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#F3F6FB;padding:32px 0">
<tr><td align="center">
<table width="580" cellpadding="0" cellspacing="0" style="max-width:580px;width:100%">
  <!-- Header -->
  <tr><td style="background:${accentColor};border-radius:12px 12px 0 0;padding:28px 36px;text-align:center">
    <div style="font-size:32px;margin-bottom:8px">${iconEmoji}</div>
    <div style="color:#fff;font-size:20px;font-weight:700;letter-spacing:-0.3px">${e(titleText)}</div>
    <div style="color:rgba(255,255,255,0.75);font-size:12px;margin-top:4px">Smart IT Helpdesk</div>
  </td></tr>
  <!-- Body -->
  <tr><td style="background:#fff;padding:36px;border-left:1px solid #E2E8F0;border-right:1px solid #E2E8F0">
    ${bodyHtml}
  </td></tr>
  <!-- Footer -->
  <tr><td style="background:#F8FAFC;border:1px solid #E2E8F0;border-top:0;border-radius:0 0 12px 12px;padding:20px 36px;text-align:center">
    <div style="color:#94A3B8;font-size:11px;line-height:1.6">
      This is an automated message from <strong>Smart IT Helpdesk</strong>.<br>
      Please do not reply to this email.
    </div>
  </td></tr>
</table>
</td></tr>
</table>
</body></html>`;

const greeting = (name) =>
  `<p style="margin:0 0 16px;font-size:16px;color:#1E293B">Hello <strong>${e(name)}</strong>,</p>`;

const divider = `<hr style="border:none;border-top:1px solid #E2E8F0;margin:24px 0">`;

const infoRow = (label, value) =>
  `<tr><td style="padding:8px 12px;font-size:13px;color:#64748B;font-weight:500;width:120px">${e(label)}</td>
   <td style="padding:8px 12px;font-size:13px;color:#1E293B">${value}</td></tr>`;

const infoTable = (rows) =>
  `<table cellpadding="0" cellspacing="0" style="width:100%;background:#F8FAFC;border:1px solid #E2E8F0;border-radius:8px;margin:16px 0">${rows}</table>`;

const ctaButton = (url, label, color) =>
  `<div style="text-align:center;margin:28px 0">
    <a href="${url}" style="display:inline-block;background:${color || '#2563EB'};color:#fff;text-decoration:none;font-weight:600;font-size:14px;padding:12px 28px;border-radius:8px;letter-spacing:0.2px">${e(label)}</a>
  </div>`;

// 6. Template rendering
let finalSubject = (payload.subject || '').trim();
let finalMessage = (payload.message || '').trim();
const recipientName = (payload.recipient_name || 'Team Member').trim();
const templateData = payload.template_data || {};

if (payload.template) {
  switch (payload.template) {

    case 'account_registration': {
      finalSubject = finalSubject || 'Registration Received - Smart IT Helpdesk';
      if (emailType === 'html') {
        finalMessage = htmlWrap(
          '#2563EB', '📋', 'Registration Received',
          greeting(recipientName) +
          `<p style="margin:0 0 20px;color:#475569;font-size:15px;line-height:1.6">
            Thank you for registering with the Smart IT Helpdesk system.
            Your account has been received and is currently <strong>pending administrator review</strong>.
          </p>` +
          infoTable(
            infoRow('Status', badge('pending')) +
            infoRow('Next step', 'Await admin approval email')
          ) +
          `<p style="margin:20px 0 0;color:#64748B;font-size:13px;line-height:1.6">
            You will receive another notification once an administrator has reviewed your registration.
            This process typically takes up to one business day.
          </p>`
        );
      } else {
        finalMessage = `Hello ${recipientName},\n\nYour Smart IT Helpdesk account registration has been received.\nYour account is pending administrator approval.\nYou will receive another email once your account is reviewed.\n\nRegards,\nSmart IT Helpdesk Team`;
      }
      break;
    }

    case 'account_approval': {
      finalSubject = finalSubject || 'Your Helpdesk Account Has Been Approved';
      const role = e(templateData.role || 'employee');
      if (emailType === 'html') {
        finalMessage = htmlWrap(
          '#16A34A', '✅', 'Account Approved',
          greeting(recipientName) +
          `<p style="margin:0 0 20px;color:#475569;font-size:15px;line-height:1.6">
            Great news! Your Smart IT Helpdesk account has been <strong>approved</strong>.
            You can now log in and start using the platform.
          </p>` +
          infoTable(
            infoRow('Status', badge('resolved')) +
            infoRow('Role assigned', `<strong style="text-transform:capitalize">${role}</strong>`)
          ) +
          ctaButton('#', 'Log In to Smart IT Helpdesk', '#16A34A') +
          divider +
          `<p style="margin:0;color:#64748B;font-size:12px">If the button above does not work, please open the application directly.</p>`
        );
      } else {
        finalMessage = `Hello ${recipientName},\n\nYour Smart IT Helpdesk account has been approved.\nRole: ${role}\n\nYou can now log in to the application.\n\nRegards,\nSmart IT Helpdesk Team`;
      }
      break;
    }

    case 'account_rejection': {
      finalSubject = finalSubject || 'Helpdesk Account Registration Update';
      const reason = e(templateData.rejection_reason || '');
      if (emailType === 'html') {
        finalMessage = htmlWrap(
          '#DC2626', '❌', 'Registration Not Approved',
          greeting(recipientName) +
          `<p style="margin:0 0 20px;color:#475569;font-size:15px;line-height:1.6">
            Thank you for your interest in the Smart IT Helpdesk system.
            Unfortunately, your registration has <strong>not been approved</strong> at this time.
          </p>` +
          (reason ? infoTable(infoRow('Reason', `<span style="color:#DC2626">${reason}</span>`)) : '') +
          `<p style="margin:20px 0 0;color:#64748B;font-size:13px;line-height:1.6">
            If you believe this was an error or require further information,
            please contact your IT administrator directly.
          </p>`
        );
      } else {
        finalMessage = `Hello ${recipientName},\n\nYour Smart IT Helpdesk registration has not been approved.${reason ? '\nReason: ' + reason : ''}\n\nPlease contact your IT administrator for more information.\n\nRegards,\nSmart IT Helpdesk Team`;
      }
      break;
    }

    case 'ticket_assignment': {
      finalSubject = finalSubject || 'New Support Ticket Assigned to You';
      const ticketId    = e(templateData.ticket_id || 'N/A');
      const ticketTitle = e(templateData.ticket_title || 'Untitled Ticket');
      const priority    = e(templateData.ticket_priority || 'medium');
      if (emailType === 'html') {
        finalMessage = htmlWrap(
          '#7C3AED', '🎫', 'Ticket Assigned to You',
          greeting(recipientName) +
          `<p style="margin:0 0 20px;color:#475569;font-size:15px;line-height:1.6">
            A support ticket has been assigned to you and requires your attention.
          </p>` +
          infoTable(
            infoRow('Ticket ID', `<strong>${ticketId}</strong>`) +
            infoRow('Title', ticketTitle) +
            infoRow('Priority', badge(priority)) +
            infoRow('Action', 'Log in to review and respond')
          ) +
          ctaButton('#', 'View Ticket', '#7C3AED') +
          `<p style="margin:0;color:#64748B;font-size:12px">Please acknowledge and begin working on this ticket promptly.</p>`
        );
      } else {
        finalMessage = `Hello ${recipientName},\n\nA support ticket has been assigned to you.\nTicket ID: ${ticketId}\nTitle: ${ticketTitle}\nPriority: ${priority}\n\nPlease log in to the Smart IT Helpdesk to review and handle this ticket.\n\nRegards,\nSmart IT Helpdesk Team`;
      }
      break;
    }

    case 'ticket_status_update': {
      finalSubject = finalSubject || 'Your Support Ticket Has Been Updated';
      const sTicketId    = e(templateData.ticket_id || 'N/A');
      const sTicketTitle = e(templateData.ticket_title || 'Untitled Ticket');
      const newStatus    = e(templateData.new_status || templateData.status || 'updated');
      if (emailType === 'html') {
        finalMessage = htmlWrap(
          '#0891B2', '🔄', 'Ticket Status Updated',
          greeting(recipientName) +
          `<p style="margin:0 0 20px;color:#475569;font-size:15px;line-height:1.6">
            There has been an update to one of your support tickets.
          </p>` +
          infoTable(
            infoRow('Ticket ID', `<strong>${sTicketId}</strong>`) +
            infoRow('Title', sTicketTitle) +
            infoRow('New Status', badge(newStatus))
          ) +
          ctaButton('#', 'View Ticket Details', '#0891B2') +
          `<p style="margin:0;color:#64748B;font-size:12px">Log in to the helpdesk portal to view the full ticket history and respond.</p>`
        );
      } else {
        finalMessage = `Hello ${recipientName},\n\nYour support ticket has been updated.\nTicket ID: ${sTicketId}\nTitle: ${sTicketTitle}\nNew Status: ${newStatus}\n\nPlease log in to view the latest details.\n\nRegards,\nSmart IT Helpdesk Team`;
      }
      break;
    }

    case 'password_reset': {
      finalSubject = finalSubject || 'Reset Your Smart IT Helpdesk Password';
      const resetUrl = String(templateData.reset_url || '').trim();
      if (!resetUrl || (!resetUrl.startsWith('https://') && !resetUrl.startsWith('http://localhost'))) {
        return [{ json: { isValid: false, statusCode: 400,
          errorMessage: "Field 'reset_url' in template_data must be a valid HTTPS URL." } }];
      }
      if (emailType === 'html') {
        finalMessage = htmlWrap(
          '#D97706', '🔑', 'Password Reset Request',
          `<p style="margin:0 0 16px;font-size:16px;color:#1E293B">Hello,</p>` +
          `<p style="margin:0 0 20px;color:#475569;font-size:15px;line-height:1.6">
            We received a request to reset the password for your Smart IT Helpdesk account.
            Click the button below to set a new password.
          </p>` +
          ctaButton(resetUrl, 'Reset My Password', '#D97706') +
          infoTable(
            infoRow('Link expires', '30 minutes') +
            infoRow('One-time use', 'Yes — link becomes invalid after use')
          ) +
          divider +
          `<p style="margin:0;color:#64748B;font-size:12px;line-height:1.6">
            If you did not request a password reset, you can safely ignore this email.
            Your password will not change.
          </p>`
        );
      } else {
        finalMessage = `Hello,\n\nWe received a request to reset your Smart IT Helpdesk password.\nReset link: ${resetUrl}\n\nThis link expires in 30 minutes and can only be used once.\nIf you did not request this, ignore this email.\n\nRegards,\nSmart IT Helpdesk Team`;
      }
      break;
    }

    default:
      return [{ json: { isValid: false, statusCode: 400,
        errorMessage: `Unknown template: '${payload.template}'.` } }];
  }
}

if (!finalSubject) {
  return [{ json: { isValid: false, statusCode: 400,
    errorMessage: "Email 'subject' cannot be empty." } }];
}
if (!finalMessage) {
  return [{ json: { isValid: false, statusCode: 400,
    errorMessage: "Email 'message' cannot be empty." } }];
}

return [{
  json: {
    isValid: true,
    to: payload.to.trim(),
    subject: finalSubject,
    message: finalMessage,
    emailType: emailType,
    isHtml: emailType === 'html',
    replyTo: payload.reply_to ? payload.reply_to.trim() : undefined,
    senderName: payload.sender_name ? payload.sender_name.trim() : 'Smart IT Helpdesk'
  }
}];

